/* Intent: Analyze digital engagement patterns by customer cohorts over time 
   Knowledge: Digital First Customer (id:14) and Customer Engagement Score (CES, id:7)
   Advanced Features: Date binning, FILTER clause */ WITH digital_cohorts AS (/* Step 1: Create quarterly cohorts based on customer tenure */ SELECT cr.clientref, TIMESTAMP_TRUNC((cr.scoredate - (cr.tenureyrs * INTERVAL '1' YEAR)), QUARTER) AS cohort_quarter, (bt.chaninvdatablock ->> '$.onlineuse' = 'High' OR bt.chaninvdatablock ->> '$.mobileuse' = 'High') /* Properly implement KB#14 Digital First Customer definition */ AND bt.chaninvdatablock ->> '$.autopay' = 'Yes' AS is_digital_first, 0.4 /* Calculate CES components */ * cah.produsescore + 0.3 * cah.chanusescore + 0.2 * bt.bankrelscore + 0.1 * (CAST(cah.custservint AS REAL) / 10) AS ces FROM core_record AS cr JOIN credit_accounts_and_history AS cah ON cr.coreregistry = cah.histcompref JOIN bank_and_transactions AS bt ON cah.histcompref = bt.bankexpref WHERE NOT bt.chaninvdatablock IS NULL) /* Step 2: Aggregate metrics by cohort and digital-first status */ SELECT cohort_quarter, is_digital_first, COUNT(*) AS cohort_size, AVG(ces) AS avg_ces /* CES metrics */, CAST(COUNT(*) /* Percentage with high engagement */ FILTER(WHERE ces > 0.7) AS REAL) / COUNT(*) AS pct_high_engagement, CAST(COUNT(*) /* Digital-first high engagement rate */ FILTER(WHERE is_digital_first AND ces > 0.7) AS REAL) / NULLIF(COUNT(*) FILTER(WHERE is_digital_first), 0) AS digital_first_high_engagement_rate FROM digital_cohorts GROUP BY cohort_quarter, is_digital_first ORDER BY cohort_quarter NULLS LAST, is_digital_first DESC NULLS FIRST

/* Intent: Analyze spread percentages across markets and correlate with market sentiment indicators 
   Knowledge Used: Spread Percentage (id:0)
   Advanced Features: JSONB operators, window functions, common table expressions */ WITH spread_calc AS (/* Step 1: Calculate spread percentage for each market using JSONB extraction */ SELECT (quote_depth_snapshot -> '$.metadata' ->> '$.mktcombo') AS market_pair, (CAST((quote_depth_snapshot -> '$.quotes' ->> '$.askquote') AS REAL) - CAST((quote_depth_snapshot -> '$.quotes' ->> '$.bidquote') AS REAL)) / CAST((quote_depth_snapshot -> '$.quotes' ->> '$.midquote') AS REAL) * 100 AS spread_pct, marketdatanode FROM marketdata), sentiment_data AS (/* Step 2: Extract market sentiment indicators from analytics */ SELECT mdataref, (market_sentiment_indicators -> '$.momentum' ->> '$.mktfeel') AS sentiment, CAST((market_sentiment_indicators -> '$.momentum' ->> '$.buyforce') AS REAL) AS buy_force FROM analyticsindicators) /* Step 3: Join and analyze spread vs sentiment with window functions */ SELECT s.market_pair, s.spread_pct, d.sentiment, d.buy_force, AVG(s.spread_pct) OVER (PARTITION BY d.sentiment) AS avg_spread_by_sentiment, PERCENT_RANK() OVER (ORDER BY s.spread_pct NULLS LAST) AS spread_percentile FROM spread_calc AS s JOIN sentiment_data AS d ON s.marketdatanode = d.mdataref ORDER BY s.spread_pct DESC NULLS FIRST
